class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        cnt = collections.defaultdict(int)
        l = 0
        best = 0

        for r in range(len(s)):
            cnt[s[r]] += 1

            while cnt[s[r]] > 2:
                cnt[s[l]] -= 1
                if cnt[s[l]] <= 0:
                    cnt.pop(s[l])
                l += 1

            best = max(best, r - l + 1)

        return best
